@[export: 'concave_gap_alignment_global']
pub fn concave_gap_alignment_global(input &i64,length usize,output &u8,capacity usize)i64{
 unsafe{if input==nil||length<5||length>26{return -1};nr:=input[0];mr:=input[1];if nr<1||nr>8||mr<1||mr>8{return -1};n:=int(nr);m:=int(mr);g:=if n>m{n}else{m};if length!=usize(2+n+m+g){return -1};mut x:=[]i64{len:n,init:0};mut y:=[]i64{len:m,init:0};mut w:=[]i64{len:g,init:0};mut p:=2;for i in 0..n{x[i]=input[p];p++;if x[i]<0||x[i]>3{return -1}};for j in 0..m{y[j]=input[p];p++;if y[j]<0||y[j]>3{return -1}};mut slope:=i64(1<<60);for k in 0..g{w[k]=input[p];p++;if w[k]<0||w[k]>100{return -1};delta:=w[k]-if k>0{w[k-1]}else{i64(0)};if k>0&&(w[k]<w[k-1]||delta>slope){return -1};slope=delta};if output==nil||capacity<8{return -2};mut dp:=[]i64{len:81,init:1<<60};dp[0]=0;for i in 0..(n+1){for j in 0..(m+1){if i==0&&j==0{continue};mut best:=i64(1<<60);if i>0&&j>0{cost:=dp[(i-1)*9+j-1];if x[i-1]!=y[j-1]{cost++};if cost<best{best=cost}};for gap in 1..(i+1){cost:=dp[(i-gap)*9+j]+w[gap-1];if cost<best{best=cost}};for gap in 1..(j+1){cost:=dp[i*9+j-gap]+w[gap-1];if cost<best{best=cost}};dp[i*9+j]=best}};bits:=u64(dp[n*9+m]);for b in 0..8{output[b]=u8((bits>>(8*b))&255)};return 8}
}
